      SUBROUTINE PLTRYZCC     PLOTS RBEND ON A VERTICAL PLANECC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DEBUG.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM5A.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'ELM38C.CIN'      INCLUDE 'ELM38D.CIN'      INCLUDE 'ELM38E.CIN'      INCLUDE 'ELM38F.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'OC.CIN'CC     LOCAL VARIABLESC      LOGICAL         HTTOP      DATA            NDB /6/C----------------------------------------------------------------------CC     CHARACTERIZE ORIENTATION OF MAGNETC      DOTOP = ABS(OPT(2,1)) .GE. 0.001      DOSIDE = ABS(OPT(1,1)) .GE. 0.001      DOENT = OPT(3,1) .GE. 0.001      DOEXIT = OPT(3,1) .LE. -0.001      ROLD = OPT(2,1) .NE. 0.0      REVERS = OPT(1,1) .LE. -0.0001      REVERS = REVERS .OR.     1         ABS(OPT(1,1)) .LT. 0.0001 .AND. OPT(2,1) .LT. -0.0001      CWISE = OPT(2,1) .LT. 0.0      IF (REVERS) CWISE = .NOT. CWISE      IF (DEBUG) WRITE (NDB,7018) DOENT, DOEXIT, DOTOP, DOSIDE, CWISE,      1                            REVERS 7018 FORMAT (' DOENT = ',L1,2X,'DOEX = ',L1,2X,'DOTOP = ',L1,2X,     1        ' DOSIDE = ',L1,2X,' CWISE = ',L1,2X,'REVERS = ',L1)CC     PROJECTIONS OF MAGNET EDGESC      DUW = OPT(1,2)*WIDE/UFLOOR(1)      DUH = OPT(2,2)*HIGH/UFLOOR(1)      DAW = OPT(1,3)*WIDE/UFLOOR(1)      DAH = OPT(2,3)*HIGH/UFLOOR(1)      IF (TYPED .EQ. 28) THEN        DUS = OPT(1,2)*SAGIT/UFLOOR(1)        DAS = OPT(1,3)*SAGIT/UFLOOR(1)      ENDIFC      IF (REVERS) THEN        IF (DEBUG) WRITE (NDB,7017) 7017   FORMAT (' TRANSVERSE COORDINATES REVERSED')        DUW = - DUW        DUH = - DUH        DAW = - DAW        DAH = - DAH        IF (TYPED .EQ. 28) THEN          DUS = - DUS          DAS = - DAS        ENDIF      ENDIF      L = LMAG      DUL = OPT(3,2)*L/UFLOOR(1)      DAL = OPT(3,3)*L/UFLOOR(1)      IF (DEBUG) WRITE (NDB,7013) DAW, DUW 7013 FORMAT (' DAW = ',F12.5,3X,'DUW = ',F12.5)      IF (DEBUG) WRITE (NDB,7014) DAH, DUH 7014 FORMAT (' DAH = ',F12.5,3X,'DUH = ',F12.5)      IF (DEBUG) WRITE (NDB,7015) DAL, DUL 7015 FORMAT (' DAL = ',F12.5,3X,'DUL = ',F12.5)      IF (DEBUG) WRITE (NDB,7016) DAS, DUS 7016 FORMAT (' DAS = ',F12.5,3X,'DUS = ',F12.5)CC     INTERSECTION OF REFERENCE TRAJECTORY WITH PROJECTEDC     DOWNSTREAM EDGEC      IF (DOEXIT .OR. DOENT) THEN        IF (DEBUG) WRITE (NDB,7012) 7012   FORMAT (' VIEW FROM DOWNSTREAM END')        GNUW = OPT(1,2)*OPT(2,3) - OPT(2,2)*OPT(1,3)        GNUS = OPT(3,2)*OPT(2,3) - OPT(2,2)*OPT(3,3)        DEN = OPT(2,2)*O(4,3,3) - O(4,3,2)*OPT(2,3)        IF (ABS(DEN) .LT. 0.00001) THEN          SW = 0.0        ELSE          SNUM = GNUW*WIDEC         IF (TYPED .EQ. 28) SNUM = SNUM + GNUS*SAGIT          SW = 0.5*SNUM/(DEN*UFLOOR(1))          SW = SIGN(SW,OPT(3,3))        ENDIF        GNU = OPT(1,3)*OPT(2,2) - OPT(1,2)*OPT(2,3)        DEN = O(4,3,3)*OPT(1,2) - OPT(1,3)*O(4,3,2)        IF (ABS(DEN) .LT. 0.00001) THEN          SH = 0.0        ELSE          SH = 0.5*GNU*HIGH/(DEN*UFLOOR(1))          SH = SIGN(SH,OPT(3,3))        ENDIF        IF (SW .EQ. 0.0) THEN          SLESS = SH        ELSE IF (SH .EQ. 0.0) THEN          SLESS = SW        ELSE          SLESS = AMIN1(SH,SW)        ENDIF        HTTOP = SH .NE. 0.0 .AND. SW .NE. 0.0 .AND. SH .LT. SW        HTTOP = SW .EQ. 0.0 .OR. HTTOP        IF (DEBUG) WRITE (NDB,7028) HTTOP 7028   FORMAT (' HTTOP = ',L2)        IF (DEBUG) WRITE (NDB,7006) SW, SH, SLESS 7006   FORMAT (' SW = ',E15.5,3X,'SH = ',E15.5,3X,'SLESS = ',E15.5)        QPLOT(1) = QORIG(1) + O(4,3,3)*SLESS        QPLOT(2) = QORIG(2) + O(4,3,2)*SLESS        IF (DEBUG) WRITE (NDB,7051) (QORIG(J), J = 1, 2) 7051   FORMAT (' QORIG = ',2F12.5)        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2) 7009   FORMAT (' QPLOT = ',2F12.5)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2) 7008   FORMAT (8F10.5)      ENDIFCC     IF FACING EXIT, TRACE ABOUT EXIT FACEC      IF (DOEXIT) THEN        IF (HTTOP .AND. CWISE) THEN          IF (DEBUG) WRITE (NDB,7023) 7023     FORMAT (' TRACE ALONG LOWER SIDE')          QPLOT(1) = QORIG(1) + 0.5*DAW - 0.5*DAH          QPLOT(2) = QORIG(2) + 0.5*DUW - 0.5*DUH          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        ENDIFC        IF (.NOT. HTTOP .OR. (HTTOP .AND. CWISE)) THEN          IF (DEBUG) WRITE (NDB,7029) 7029     FORMAT (' TRACE ALONG FAR FACE')          QPLOT(1) = QORIG(1) + 0.5*DAW + 0.5*DAH          QPLOT(2) = QORIG(2) + 0.5*DUW + 0.5*DUH          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        ENDIFC        IF (DEBUG) WRITE (NDB,7022) 7022   FORMAT (' LOOP AROUND EXIT FACE')        QPLOT(1) = QORIG(1) - 0.5*DAW + 0.5*DAH        QPLOT(2) = QORIG(2) - 0.5*DUW + 0.5*DUH        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        QPLOT(1) = QPLOT(1) - DAH        QPLOT(2) = QPLOT(2) - DUH        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        QPLOT(1) = QPLOT(1) + DAW        QPLOT(2) = QPLOT(2) + DUW        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        QPLOT(1) = QPLOT(1) + DAH        QPLOT(2) = QPLOT(2) + DUH        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        QPLOT(1) = QPLOT(1) - 0.5*DAW        QPLOT(2) = QPLOT(2) - 0.5*DUW      ENDIFCC     IF NOT FACING EXIT, TRACE APPROPRIATE EXIT EDGESC      IF (DOENT .AND. DOSIDE) THEN        IF (HTTOP .AND. CWISE) THEN          QPLOT(1) = QORIG(1) + 0.5*DAH - 0.5*DAW          QPLOT(2) = QORIG(2) + 0.5*DUH - 0.5*DUW          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        ENDIF        IF (HTTOP .AND. .NOT. CWISE) THEN          QPLOT(1) = QORIG(1) - 0.5*DAH - 0.5*DAW          QPLOT(2) = QORIG(2) - 0.5*DUH - 0.5*DUW          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        ENDIF        QPLOT(1) = QORIG(1) - 0.5*DAW        QPLOT(2) = QORIG(2) - 0.5*DUW        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)      ENDIFC      IF (DOEXIT .AND. DOSIDE) THEN        IF (DEBUG) WRITE (NDB,7030) 7030   FORMAT (' TRANSITION FROM EXIT FACE TO SIDE')        QPLOT(1) = QPLOT(1) - 0.5*DAW        QPLOT(2) = QPLOT(2) - 0.5*DUW        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        QPLOT(1) = QPLOT(1) - 0.5*DAH        QPLOT(2) = QPLOT(2) - 0.5*DUH      ENDIFC      IF (DOSIDE .AND. DOTOP .AND. .NOT. DOENT .AND. .NOT. DOEXIT) THEN        QPLOT(1) = QORIG(1) - 0.5*DAW        QPLOT(2) = QORIG(2) - 0.5*DUW      ENDIFCC     VIEW FROM SIDEC      IF (DOSIDE) THEN        IF (DEBUG) WRITE (NDB,7011) 7011   FORMAT (' VIEW FROM SIDE')        QPLOT(1) = QPLOT(1) + 0.5*DAH        QPLOT(2) = QPLOT(2) + 0.5*DUH        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        QPLOT(1) = QPLOT(1) - DAL        QPLOT(2) = QPLOT(2) - DUL        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        QPLOT(1) = QPLOT(1) - DAH        QPLOT(2) = QPLOT(2) - DUH        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        IF (DOENT) THEN          IF (DEBUG) WRITE (NDB,7021) 7021     FORMAT (' LOOP AROUND ENTRANCE FACE')          QPLOT(1) = QPLOT(1) + DAW          QPLOT(2) = QPLOT(2) + DUW          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          QPLOT(1) = QPLOT(1) + DAH          QPLOT(2) = QPLOT(2) + DUH          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          QPLOT(1) = QPLOT(1) - DAW          QPLOT(2) = QPLOT(2) - DUW          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          QPLOT(1) = QPLOT(1) - DAH          QPLOT(2) = QPLOT(2) - DUH          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          IF (DEBUG) WRITE (NDB,7091) 7091     FORMAT (' VIEW FROM SIDE')        ENDIF        QPLOT(1) = QPLOT(1) + DAL        QPLOT(2) = QPLOT(2) + DUL        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        QPLOT(1) = QPLOT(1) + 0.5*DAH        QPLOT(2) = QPLOT(2) + 0.5*DUH      ENDIFC      IF (DOSIDE .AND. .NOT. DOTOP) THEN        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)      ENDIFCC     TRANSITION FROM TOP TO SIDEC      IF (DOSIDE .AND. DOTOP) THEN        IF (DEBUG) WRITE (NDB,7026) 7026   FORMAT (' TRANSITION FROM TOP TO SIDE')        IF (CWISE) THEN          QPLOT(1) = QPLOT(1) + 0.5*DAH          QPLOT(2) = QPLOT(2) + 0.5*DUH        ELSE          QPLOT(1) = QPLOT(1) - 0.5*DAH          QPLOT(2) = QPLOT(2) - 0.5*DUH        ENDIF        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        QPLOT(1) = QPLOT(1) + 0.5*DAW        QPLOT(2) = QPLOT(2) + 0.5*DUW      ENDIFCC     VIEW FROM TOPC      IF (DOTOP) THEN        IF (DEBUG) WRITE (NDB,7010) 7010   FORMAT (' VIEW FROM TOP')        QPLOT(1) = QPLOT(1) + 0.5*DAW        QPLOT(2) = QPLOT(2) + 0.5*DUW        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        QPLOT(1) = QPLOT(1) - DAL        QPLOT(2) = QPLOT(2) - DUL        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        QPLOT(1) = QPLOT(1) - DAW        QPLOT(2) = QPLOT(2) - DUW        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        IF (DOENT .AND. .NOT. DOSIDE) THEN          IF (DEBUG) WRITE (NDB,7027) 7027     FORMAT (' LOOP AROUND ENTRANCE FACE')          QPLOT(1) = QPLOT(1) - DAH          QPLOT(2) = QPLOT(2) - DUH          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          QPLOT(1) = QPLOT(1) + DAW          QPLOT(2) = QPLOT(2) + DUW          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          QPLOT(1) = QPLOT(1) + DAH          QPLOT(2) = QPLOT(2) + DUH          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          QPLOT(1) = QPLOT(1) - DAW          QPLOT(2) = QPLOT(2) - DUW          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          IF (DEBUG) WRITE (NDB,7090) 7090     FORMAT (' VIEW FROM TOP')        ENDIF        QPLOT(1) = QPLOT(1) + DAL        QPLOT(2) = QPLOT(2) + DUL        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        QPLOT(1) = QPLOT(1) + 0.5*DAW        QPLOT(2) = QPLOT(2) + 0.5*DUW        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)      ENDIFCC     LOOP AROUND EXIT FACEC      IF (DOEXIT) THEN        IF (DEBUG) WRITE (NDB,7020) 7020   FORMAT (' LOOP AROUND EXIT FACE')        IF (DOSIDE .AND. DOTOP .AND. CWISE) THEN          QPLOT(1) = QPLOT(1) - 0.5*DAW          QPLOT(2) = QPLOT(2) - 0.5*DUW          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          QPLOT(1) = QPLOT(1) - 0.5*DAH          QPLOT(2) = QPLOT(2) - 0.5*DUH        ENDIFC        IF (DOSIDE .AND. (.NOT. ROLD .OR. CWISE)) THEN          QPLOT(1) = QPLOT(1) - 0.5*DAH          QPLOT(2) = QPLOT(2) - 0.5*DUH          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)          QPLOT(1) = QPLOT(1) + 0.5*DAW          QPLOT(2) = QPLOT(2) + 0.5*DUW        ENDIFC        IF (.NOT. HTTOP .OR. (HTTOP .AND. .NOT. CWISE)) THEN          QPLOT(1) = QORIG(1) + 0.5*DAW - 0.5*DAH          QPLOT(2) = QORIG(2) + 0.5*DUW - 0.5*DUH          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        ENDIFC        IF (HTTOP .AND. .NOT. CWISE) THEN          QPLOT(1) = QORIG(1) + 0.5*DAW + 0.5*DAH          QPLOT(2) = QORIG(2) + 0.5*DUW + 0.5*DUH          IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)          WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        ENDIF      ENDIFC      IF (DEBUG) WRITE (NDB,7031) 7031 FORMAT (' RETURN TO REFERENCE TRAJECTORY EXIT POINT')      IF (DOENT .AND. .NOT. HTTOP) THEN        QPLOT(1) = QPLOT(1) - 0.5*DAW        QPLOT(2) = QPLOT(2) - 0.5*DUW        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)      ENDIFCC     REFERENCE TRAJECTORY AT EXIT FACEC      IF (DOEXIT .OR. DOENT) THEN        QPLOT(1) = QORIG(1) + O(4,3,3)*SLESS        QPLOT(2) = QORIG(2) + O(4,3,2)*SLESS        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)        QPLOT(1) = QORIG(1)        QPLOT(2) = QORIG(2)        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)      ELSE IF (TYPED .EQ. 28) THEN        QPLOT(1) = QPLOT(1) - DAS        QPLOT(2) = QPLOT(2) - DUS        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)      ELSE        QPLOT(1) = QORIG(1)        QPLOT(2) = QORIG(2)        IF (DEBUG) WRITE (NDB,7009) (QPLOT(J), J = 1, 2)        WRITE (NPLOT,7008) (QPLOT(J), J = 1, 2)      ENDIF      RETURN      END